list_tax_custom_profiles.code:
final response = await client.taxCustomProfiles
    .listTaxCustomProfiles(queryParams: {'limit': 20});
final customProfiles = (response.map as Map)['custom_profiles'] as List;
for (final customProfile in customProfiles) {
  print('${(customProfile as Map)['id']} ${customProfile['name']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print(pagination['total']);

create_tax_custom_profile.code:
final response = await client.taxCustomProfiles.createTaxCustomProfile({
  'custom_profile': {
    'name': 'Wholesale customers',
    'description': 'Rates for wholesale accounts',
  },
});
final customProfile = (response.map as Map)['custom_profile'] as Map;
print(customProfile['id']);

get_tax_custom_profile.code:
final response = await client.taxCustomProfiles.getTaxCustomProfile(1);
final customProfile = (response.map as Map)['custom_profile'] as Map;
print('${customProfile['name']} ${customProfile['rate_rules_count']}');
final rateRules = customProfile['rate_rules'] as List;
for (final rateRule in rateRules) {
  print('${(rateRule as Map)['id']} ${rateRule['name']}');
}

